import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"Post-#332 orphan status (provenance backfill, 2026-06-12)","description":"","frontmatter":{},"headers":[],"relativePath":"provenance/post-332-orphan-status.md","filePath":"provenance/post-332-orphan-status.md"}'),d={name:"provenance/post-332-orphan-status.md"};function n(i,e,r,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="post-332-orphan-status-provenance-backfill-2026-06-12" tabindex="-1">Post-#332 orphan status (provenance backfill, 2026-06-12) <a class="header-anchor" href="#post-332-orphan-status-provenance-backfill-2026-06-12" aria-label="Permalink to &quot;Post-#332 orphan status (provenance backfill, 2026-06-12)&quot;">​</a></h1><p>This document captures the state of <code>static/data/image-provenance.json</code> after the #332 / #5 Phase 0/1/5 work, and what remains as work-to-do for full manifest coverage.</p><h2 id="disk-vs-manifest-by-surface" tabindex="-1">Disk vs manifest, by surface <a class="header-anchor" href="#disk-vs-manifest-by-surface" aria-label="Permalink to &quot;Disk vs manifest, by surface&quot;">​</a></h2><p>After fixing the <code>buildFleetEntries</code> shape mismatch (252 fleet-image-sources entries authored by the post-2026-06 <code>fetch-assets.ts</code> use a <code>{commons_file, commons_url, credit, license}</code> shape that the build script was crashing on), the manifest covers <strong>4417 of 8609</strong> files on disk:</p><table tabindex="0"><thead><tr><th>Surface</th><th>On disk</th><th>In manifest</th><th>Orphan</th></tr></thead><tbody><tr><td>fleet-galleries</td><td>4344</td><td>~851</td><td>~3493</td></tr><tr><td>missions</td><td>1637</td><td>~1100</td><td>~537</td></tr><tr><td>iss-modules</td><td>576</td><td>576</td><td>0</td></tr><tr><td>mars-sites</td><td>448</td><td>448</td><td>0</td></tr><tr><td>moon-sites</td><td>308</td><td>308</td><td>0</td></tr><tr><td>science</td><td>296</td><td>74</td><td>222</td></tr><tr><td>earth-objects</td><td>204</td><td>204</td><td>0</td></tr><tr><td>hotspots</td><td>184</td><td>19</td><td>165</td></tr><tr><td>planets</td><td>160</td><td>160</td><td>0</td></tr><tr><td>tiangong-modules</td><td>136</td><td>136</td><td>0</td></tr><tr><td>recommendations</td><td>124</td><td>31</td><td>93</td></tr><tr><td>small-bodies</td><td>104</td><td>104</td><td>0</td></tr><tr><td>rockets</td><td>52</td><td>13</td><td>39</td></tr><tr><td>sun</td><td>20</td><td>20</td><td>0</td></tr><tr><td>satellites</td><td>16</td><td>0</td><td>16</td></tr></tbody></table><h2 id="root-cause-of-the-remaining-orphans" tabindex="-1">Root cause of the remaining orphans <a class="header-anchor" href="#root-cause-of-the-remaining-orphans" aria-label="Permalink to &quot;Root cause of the remaining orphans&quot;">​</a></h2><p>The bulk (≈ 3600 of 4584 orphans) is <strong>derivative variants</strong> — the <code>.16x9.jpg</code> / <code>.4x3.jpg</code> / <code>.1x1.jpg</code> files produced by the image resizing step. <code>buildFleetEntries</code>, <code>buildMissionGalleryEntries</code>, and a few others emit <em>one provenance row per logical slot</em> rather than one row per file on disk. The variant files inherit their license + author from the base, but they aren&#39;t enumerated in the manifest.</p><p>Two fixes are possible and both should be discussed with Marko before landing:</p><ol><li><p><strong>Inherit-on-walk</strong>: after writing an entry for <code>&lt;id&gt;/01.jpg</code>, also write entries for <code>&lt;id&gt;/01.16x9.jpg</code>, <code>&lt;id&gt;/01.4x3.jpg</code>, and <code>&lt;id&gt;/01.1x1.jpg</code> with <code>modifications: [...base, &#39;resampled-16x9&#39;]</code> etc. Pure manifest expansion; no fetch-assets changes.</p></li><li><p><strong>Treat variants as out-of-scope</strong>: amend the doc + the validate-data gate to assert &quot;every base file (<code>&lt;id&gt;/&lt;NN&gt;.&lt;ext&gt;</code>) has a manifest entry&quot; and stop trying to track variants. Simpler, and arguably correct since the variants are pipeline output, not curated content.</p></li></ol><h3 id="slice-b-c-mission-heroes-—-true-orphans" tabindex="-1">Slice B/C mission heroes — true orphans <a class="header-anchor" href="#slice-b-c-mission-heroes-—-true-orphans" aria-label="Permalink to &quot;Slice B/C mission heroes — true orphans&quot;">​</a></h3><p>After variants, the residual real-content gap is <strong>29 mission heroes</strong> with no <code>MISSION_IMAGE_QUERIES</code> curated entry:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apollo-1, apollo-soyuz, beresheet, change3, inspiration4,</span></span>
<span class="line"><span>luna16, luna21, mariner10,</span></span>
<span class="line"><span>otv-1, otv-2, otv-3, otv-4, otv-5, otv-6, otv-7,</span></span>
<span class="line"><span>polaris-dawn, schiaparelli, shenzhou-1,</span></span>
<span class="line"><span>skylab-2, skylab-3, skylab-4,</span></span>
<span class="line"><span>voskhod-1, voskhod-2,</span></span>
<span class="line"><span>vostok-1, vostok-2, vostok-3, vostok-4, vostok-5, vostok-6</span></span></code></pre></div><p>These are the missions whose hero files were created during #5 Phase 0 without a corresponding curated entry in <code>scripts/fetch-assets.ts</code>.</p><p><strong>Why this is not a trivial add:</strong> dropping a <code>{ id, query }</code> entry into <code>MISSION_IMAGE_QUERIES</code> will cause the next <code>npm run fetch-assets</code> run to refetch from NASA Images API and overwrite the Phase 0 imagery. So either:</p><ul><li><strong>Annotate the existing files</strong> with <code>commonsCoverFirst</code> titles matched to what was actually placed during Phase 0 (manual + careful per-mission inspection), or</li><li><strong>Add a <code>manifestOnly: true</code> flag</strong> to <code>MissionImageQuery</code> that the build script honours (manifest entry yes, fetch-assets refetch no), or</li><li><strong>Rework <code>buildMissionGalleryEntries</code></strong> to walk the on-disk dirs like <code>buildPanelEntries</code> does, emitting <code>direct-other</code> / <code>curated-no-upstream-record</code> entries for any directory not in the curated map.</li></ul><p>Option 3 is the most automatic but the laxest about provenance honesty; Option 1 keeps the <code>direct-other</code> rate low but is the most manual.</p><h3 id="smaller-residuals" tabindex="-1">Smaller residuals <a class="header-anchor" href="#smaller-residuals" aria-label="Permalink to &quot;Smaller residuals&quot;">​</a></h3><ul><li><strong>science (222), hotspots (165), recommendations (93), rockets (39), satellites (16):</strong> the build script has dedicated walkers for science <ul><li>hotspots + recommendations + rockets but each one walks a curated metadata map rather than the filesystem. New files added to these surfaces since the last metadata-map update aren&#39;t picked up. Each surface needs a metadata-map sync + re-run.</li></ul></li></ul><h2 id="what-landed-in-this-commit" tabindex="-1">What landed in this commit <a class="header-anchor" href="#what-landed-in-this-commit" aria-label="Permalink to &quot;What landed in this commit&quot;">​</a></h2><ul><li><code>scripts/build-image-provenance.ts</code> — <code>buildFleetEntries</code> now handles both legacy <code>{agency, sourceUrl}</code> and new <code>{commons_file, commons_url, credit, license}</code> source-manifest shapes via a tagged-union dispatch. The new shape skips the URL regex parse because it carries the Commons filename directly. No behaviour change for the 851 legacy entries; recovers the 252 entries that were crashing the build.</li><li><code>static/data/image-provenance.json</code> — regenerated; +233 net entries (4184 → 4417).</li></ul><h2 id="what-did-not-land" tabindex="-1">What did NOT land <a class="header-anchor" href="#what-did-not-land" aria-label="Permalink to &quot;What did NOT land&quot;">​</a></h2><ul><li>Mission <code>MISSION_IMAGE_QUERIES</code> additions for the 29 unscored heroes (needs design input — see above).</li><li>Variant-inheritance walk in <code>buildFleetEntries</code> / <code>buildMissionGalleryEntries</code> (needs design input).</li><li>Vision rescoring for the 29 unscored heroes (~$1 cost; pending Marko&#39;s explicit budget approval).</li></ul><h2 id="refs" tabindex="-1">Refs <a class="header-anchor" href="#refs" aria-label="Permalink to &quot;Refs&quot;">​</a></h2><ul><li>#332 umbrella PR</li><li>#5 follow-up (post-332-follow-ups.md item 5: mission image rework)</li></ul>`,24)])])}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
